/* Two independent transaction workpapers; selections stay only in this open page. */
(function(){
 const law='https://law-out.mof.gov.tw/LawContent.aspx?id=FL033412',oecd='https://www.oecd.org/content/dam/oecd/en/publications/reports/2022/01/oecd-transfer-pricing-guidelines-for-multinational-enterprises-and-tax-administrations-2022_57104b3a/0e655865-en.pdf';
 const methods={cup:['可比較未受控價格法','第10條、第14條','適合以高度可比的獨立交易價格直接比較；本案尚缺產品、數量、品質、交貨及市場條件一致的價格，現有公司淨利資料不能代替單價。'],rpm:['再售價格法','第10條、第16條','須能可靠衡量再售毛利及功能差異。本案A從事製造，非單純買入後再售，且未提供一致口徑的可比再售毛利。'],cost:['成本加價法','第10條、第17條','製造交易可考慮以成本及毛利加價比較，但須成本分類一致且有可比毛利資料；本案提供的是營業淨利指標，不能把32.00%當成毛利加價率。'],cpm:['可比較利潤法','第10、11、18條','本案提供可比分部淨利資料，可在FAR、受測個體及會計口徑可比的前提下，進行單邊利潤檢測；本案屬資料支持下的教學選擇，不代表所有製造或授權交易均應採用。'],split:['利潤分割法','第10、11、19條','若雙方均有獨特且有價值的貢獻、高度整合或共同承擔重大風險，可評估本法；本案尚缺可靠合併利潤、例行報酬及分割因子，不能只憑集團利潤或人數分割。'],cut:['可比較未受控交易法','第11、15條','可用於無形資產移轉或使用，須有可比授權標的、權利範圍、年限、市場及條款。本案未提供可直接使用的獨立授權交易。'],income:['收益法','第11、19條之1','無形資產交易可評估收益法，但需可信賴現金流量、折現率、年限與情境假設，本案尚未提供。'],other:['其他經財政部核定之常規交易方法','第10、11條','應確認適用交易、方法核定依據及可靠資料；不能把自行設計的算法逕當成已核定方法。']};
 const plis={roa:['營業資產報酬率','營業淨利 ÷ 營業資產','適合報酬與營業資產投入關聯較強的活動；本案尚缺兩方可比營業資產及一致估價資料，不能由成本或銷貨利潤率反推。'],sales:['營業淨利率','營業淨利 ÷ 銷貨淨額','可用於銷貨口徑可靠的受測活動；本案未回銷分部提供26.30%及銷貨口徑的可比資料。仍須核對銷貨範圍及受控因素對分母的影響。'],berry:['貝里比率','營業毛利 ÷ 營業費用','須評估營業費用是否適當反映功能價值及成本分類一致性；本案製造含材料、設備等投入，尚無充分理由用營業費用獨立代表貢獻，也缺可比毛利與費用拆分。'],cost:['成本及營業費用淨利率','營業淨利 ÷（營業成本＋營業費用）','可在成本費用合理反映製造活動、分類及分攤一致時評估；本案回銷分部提供32.00%及同口徑資料。並非成本加價法的毛利加價率。']};
 const testedRule='受測個體應與交易的功能、資產及風險分析一致，通常選擇功能相對簡單、能取得可靠可比資料、所需差異調整較少且結果較可信賴的一方。原則上不應具有使單邊比較失真的高價值或獨特無形資產／特有資產；若其所用資產與可比對象類似，仍須具體評估。這樣較容易找到功能風險相近的獨立企業，並非只看公司名稱或要求完全沒有任何無形資產。';
 const fresh=()=>({step:0,far:{},party:'',method:'',pli:'',selected:[],region:'全部',sector:'全部',reviewed:false,done:false});
 if(!state.aWorkflow)state.aWorkflow={active:'return',return:fresh(),nonreturn:fresh()};
 for(const key of ['return','nonreturn']){const p=state.aWorkflow[key]={...fresh(),...state.aWorkflow[key]};p.selected=[];p.done=false;p.reviewed=false;p.step=0}
 state.aWorkflow.active='return';
 const w=()=>state.aWorkflow,part=()=>w()[w().active],name=key=>key==='return'?'回銷':'未回銷',farOK=p=>farCards.every(([k])=>p.far[k]),expected=key=>key==='return'?'cost':'sales';
 function valid(key){const p=w()[key];return farOK(p)&&p.party==='A'&&p.method==='cpm'&&p.pli===expected(key)&&p.selected.length>0}
 function result(key){const p=w()[key],r=TPAAdjustment.evaluate({selected:companies.filter(c=>p.selected.includes(c.id)),farReady:farOK(p),returnParty:p.party})[key];if(!valid(key))return {...r,status:p.party==='甲'?'complex':'pending',rawAdjustment:null,adjustment:0,reason:p.party==='甲'?'甲公司功能複雜，尚缺可可靠比較的完整FAR與報酬資料。':p.method!=='cpm'?'所選方法尚缺本案可用的直接價格、毛利、合併利潤或估值資料；本段不以淨利率替代計算。':p.pli!==expected(key)?'本分部沒有這項指標所需的可靠原始分母及可比資料，不能直接套用其他指標的32.00%或26.30%。':!farOK(p)?'本分部FAR尚未完成。':'請選擇受測個體及本分部可比樣本。'};return r}
 function invalidate(key){const p=w()[key];p.done=false;p.reviewed=false;if(key==='return'){w().nonreturn=fresh();w().active='return'}}
 window.AStages={methods,plis,testedRule,result,valid,fresh,
 change(field,value){const key=w().active;invalidate(key);part()[field]=value;if(field==='method')part().pli='';save();render()},
 far(key,value){invalidate(w().active);part().far[key]=value;save();render()},
 sample(id){const p=part();invalidate(w().active);p.selected=p.selected.includes(id)?p.selected.filter(v=>v!==id):[...p.selected,id];save();render()},
 clear(){invalidate(w().active);part().selected=[];save();render()},
 filter(key,value){part()[key]=value;save();render()},
 next(){const p=part();if(!canNext(p))return;p.step++;save();render()},
 edit(step){part().step=step;invalidate(w().active);save();render()},
 confirm(value){part().reviewed=value;save();render()},
 finish(){const p=part();if(!p.reviewed)return;p.done=true;p.step=6;if(w().active==='return')w().active='nonreturn';save();render()},
 show(key){if(key==='nonreturn'&&!w().return.done)return;w().active=key;save();render()}
 };
 function canNext(p){return p.step===0?farOK(p):p.step===1?!!p.party:p.step===2?!!p.method:p.step===3?p.method!=='cpm'||!!p.pli:p.step===4?p.selected.length>0||p.method!=='cpm'||p.party==='甲':false}
 function methodReason(key,m){const base=methods[m][2];return key==='return'&&['cut','income'].includes(m)?'本段為有形產品回銷，第10條的方法範圍優先適用；本方法屬無形資產交易工具，不能未界定交易即混用。'+base:key==='nonreturn'&&['cup','rpm','cost'].includes(m)?'本段以甲公司技術授權報酬為查核焦點，先依第11條評估；不得未說明即套入有形產品交易方法。'+base:base}
 function pliReason(key,pli){return (pli===expected(key)?'本段有對應分母及利潤資料，可優先評估。':'本段目前未選用；若改採此指標，須重新建立受測及可比財務口徑。')+plis[pli][2]}
 const sources=`<p class="note">法規依據：<a href="${law}" target="_blank" rel="noopener">我國查準第7條第2、3款、第9條、第10、11條、第18條第3、4、6項、第20條、第22條第1項第4款第8目</a>；<a href="${oecd}" target="_blank" rel="noopener">OECD TPG 2022 §§2.2、2.8、2.12、2.82–2.107、3.18、6.201、6.205–6.206</a>。成本及營業費用淨利率於我國須另確認第18條第4項第4款之核定適用依據；本案列為教學指標，不宣稱本題數值已獲核定。單年度樣本亦不等於已完成法定多年度分析。</p>`;
 chapter1=function(){const key=w().active,p=part(),n=name(key),e=expected(key),r=result(key),st=p.step,chosen=companies.filter(c=>p.selected.includes(c.id)),filtered=companies.filter(c=>(p.region==='全部'||c.region===p.region)&&(p.sector==='全部'||c.sector===p.sector));
 let body=`<h2>第二章｜A公司：兩段交易查核</h2><div class="story">🏭 <b>A公司財務主管：</b>「請先完成產品回銷的調查及結論，再另開技術授權與未回銷的底稿。兩段不共用選樣，也不沿用前段調查勾選。」</div><div class="toolbar"><button onclick="AStages.show('return')">第一段｜回銷 ${w().return.done?'✓':''}</button><button onclick="AStages.show('nonreturn')" ${w().return.done?'':'disabled'}>第二段｜未回銷 ${w().nonreturn.done?'✓':w().return.done?'':'🔒'}</button></div><h3>${n}查核｜步驟 ${Math.min(st+1,6)}／6</h3><p>流程：FAR → 受測個體 → 最適方法 → 利潤率指標 → 本段選樣 → 檢測與調整。</p><div class="lead">本段計算基礎：${money(r.base)}千元；提供指標：${r.indicator} ${fmt(r.actual)}${key==='nonreturn'?'；已收權利金600,000千元':''}。</div>`;
 if(st===0)body+=`<div class="panel" id="far-investigation"><h3>① ${n}FAR調查卡</h3>${farCards.map(([k,t,d])=>`<label><input type="checkbox" aria-label="${n}FAR：${t}" ${p.far[k]?'checked':''} onchange="AStages.far('${k}',this.checked)"> ${t}</label><p>${d}</p>`).join('')}<p>本段交易範圍：${key==='return'?'A製造後銷回甲公司的產品交易。':'A未回銷產品所涉及的甲公司技術授權報酬；應核對授權範圍、分部收益與已有補償，不能把第三方產品銷售本身誤認成受控交易。'}</p></div>`;
 if(st===1)body+=`<div class="panel"><h3>② ${n}受測個體</h3><p>${testedRule}</p>${sources}<label>${n}交易受測個體 <select aria-label="${n}交易受測個體" onchange="AStages.change('party',this.value)"><option value="">請選擇</option>${['A','甲'].map(v=>`<option ${p.party===v?'selected':''}>${v}</option>`).join('')}</select></label><p>${p.party==='A'?'本案教學假設：A的受測活動相對單純，尚未辨認出妨礙比較的獨特高價值資產；仍須用FAR及技術紀錄驗證，不能由研發比率為零直接推定。':p.party==='甲'?'甲涉及總部、研發與技術權利，功能較複雜；目前未建立可靠可比分析，不能移用A的利潤率。':'請先依交易實質及資料可靠性作選擇。'}</p></div>`;
 if(st===2)body+=`<div class="panel"><h3>③ 選擇最適常規交易方法</h3><p>依我國查準第7條第2款、第9條及OECD TPG §§2.2、2.8、2.12，以交易特性、FAR、可比性及資料可靠性決定；不須機械試算所有方法。</p><select aria-label="${n}最適常規交易方法" onchange="AStages.change('method',this.value)"><option value="">請選擇</option>${Object.entries(methods).map(([k,v])=>`<option value="${k}" ${p.method===k?'selected':''}>${v[0]}</option>`).join('')}</select>${Object.entries(methods).map(([k,v])=>`<details ${p.method===k?'open':''}><summary>${p.method===k?'已選擇':'未選擇'}｜${v[0]}（${v[1]}）</summary><p>${methodReason(key,k)}</p></details>`).join('')}</div>`;
 if(st===3)body+=`<div class="panel"><h3>④ 最適利潤率指標</h3>${p.method==='cpm'?`<p>依查準第18條第4–6項及OECD TPG §§2.82–2.107，檢查活動性質、分母與價值來源、資料及會計分類的可靠性。</p><select aria-label="${n}最適利潤率指標" onchange="AStages.change('pli',this.value)"><option value="">請選擇</option>${Object.entries(plis).map(([k,v])=>`<option value="${k}" ${p.pli===k?'selected':''}>${v[0]}</option>`).join('')}</select>${Object.entries(plis).map(([k,v])=>`<details ${p.pli===k?'open':''}><summary>${p.pli===k?'已選擇':'未選擇'}｜${v[0]}</summary><p>${v[1]}。${pliReason(key,k)}</p></details>`).join('')}`:'<p>本段未選可比較利潤法，不強制選擇淨利指標；應依所選方法取得價格、毛利或估值資料，不能沿用本頁淨利率試算。</p>'}${sources}</div>`;
 if(st===4)body+=`<div class="panel" id="comparable-lab"><h3>⑤ ${n}獨立選樣</h3><p>已選方法：${methods[p.method]?.[0]||'未選'}；已選指標：${plis[p.pli]?.[0]||'不適用'}。</p>${p.method!=='cpm'||p.party==='甲'?'<p>目前公司淨利資料不足以執行所選方案。可記錄資料不足後進入本段結論，或返回前步修正選擇。</p>':`<div class="toolbar"><label>地區 <select aria-label="可比公司地區" onchange="AStages.filter('region',this.value)">${['全部','亞太','歐洲','美洲'].map(v=>`<option ${p.region===v?'selected':''}>${v}</option>`).join('')}</select></label><label>產業 <select aria-label="可比公司產業" onchange="AStages.filter('sector',this.value)">${['全部',...sectors].map(v=>`<option ${p.sector===v?'selected':''}>${v}</option>`).join('')}</select></label><button onclick="AStages.clear()">清空本段</button></div><div class="scroll"><table><tr><th>選取</th><th>公司</th><th>地區／產業</th><th>研發營收比</th><th>營業淨利率</th><th>成本及營業費用淨利率</th></tr>${filtered.map(c=>`<tr><td><input type="checkbox" aria-label="選取${c.name}" ${p.selected.includes(c.id)?'checked':''} onchange="AStages.sample(${c.id})"></td><td>${c.name}</td><td>${c.region}／${c.sector}</td><td>${fmt(c.rd)}</td><td>${fmt(c.margin)}</td><td>${fmt(c.fullCostMargin)}</td></tr>`).join('')}</table></div><p>本段已選 ${chosen.length} 家。兩分部選樣各自獨立；重新開啟頁面均不預勾選。</p>`}</div>`;
 if(st>=5)body+=`<div class="panel" id="a-adjustments"><h3>⑥ ${n}檢測與調整</h3><p>本段採用：${methods[p.method]?.[0]||'未選'}；指標：${p.method==='cpm'?(plis[p.pli]?.[0]||'未選'):'不適用'}；受測個體：${p.party||'未選'}公司。</p>${valid(key)?segmentResult(r):`<p class="lead">${r.reason}</p><p>調整金額：尚無足夠資料計算，不以0元表示已完成量化結論。</p>`}<p class="note">保留前述題目指定的課稅方向、四分位範圍及調整公式，屬教學試算；不等同依法核實調整或補稅。</p>${st===5?`<label><input type="checkbox" ${p.reviewed?'checked':''} onchange="AStages.confirm(this.checked)"> 我已檢視本段方法、指標、選樣、反證及${valid(key)?'調整結果':'資料不足的限制'}。</label><p><button onclick="AStages.finish()" ${p.reviewed?'':'disabled'}>${key==='return'?'完成回銷，進入未回銷調查 →':'完成未回銷，彙整兩段結論 →'}</button></p>`:'<p>✓ 本段查核紀錄已完成。</p>'}</div>`;
 if(st<5)body+=`<button onclick="AStages.next()" ${canNext(p)?'':'disabled'}>確認本步，繼續 →</button>`;
 if(st>0)body+=`<p class="toolbar">${['FAR','受測個體','最適方法','利潤指標','本段選樣'].map((v,i)=>i<st?`<button onclick="AStages.edit(${i})">返回修改${v}</button>`:'').join('')}</p>`;
 if(w().return.done&&w().nonreturn.done)body+=aAdjustmentPanel()+quiz('a');return body};
 aAdjustment=function(){const back=result('return'),other=result('nonreturn');return {return:back,nonreturn:other,total:back.adjustment+other.adjustment}};
 window.aStageReportBlocks=function(){const blocks=[];for(const key of ['return','nonreturn']){const p=w()[key],r=result(key);blocks.push({type:'subheading',text:name(key)+'交易獨立底稿'},{type:'p',text:'進度：'+(p.done?'完成本段檢視':'尚未完成')+'；受測個體：'+(p.party||'未選')+'；方法：'+(methods[p.method]?.[0]||'未選')+'；利潤指標：'+(p.method==='cpm'?(plis[p.pli]?.[0]||'未選'):'不適用')},{type:'p',text:testedRule},{type:'p',text:'法規：我國查準第7、9、10、11、18、20、22條；OECD TPG 2022 §§2.2、2.8、2.12、3.18。'});for(const [k,m]of Object.entries(methods))blocks.push({type:'p',text:(p.method===k?'選擇':'未選擇')+m[0]+'：'+methodReason(key,k)});if(p.method==='cpm')for(const [k,v]of Object.entries(plis))blocks.push({type:'p',text:(p.pli===k?'選擇':'未選擇')+v[0]+'：'+pliReason(key,k)});blocks.push({type:'p',text:'本段FAR：'+farCards.map(([k,t])=>(p.far[k]?'已確認':'未確認')+' '+t).join('；')},{type:'table',headers:['公司','營業淨利率','成本及營業費用淨利率'],rows:companies.filter(c=>p.selected.includes(c.id)).map(c=>[c.name,fmt(c.margin),fmt(c.fullCostMargin)]),widths:[2,1,1]},{type:'p',text:r.reason},{type:'p',text:r.stats?'可比第25分位 '+fmt(r.stats.q25)+'；中位數 '+fmt(r.stats.median)+'；第75分位 '+fmt(r.stats.q75)+'。':'未建立可比常規區間。'},{type:'p',text:valid(key)?segmentFormula(r)+'；甲公司本分部所得調整 '+money(r.adjustment)+'千元。':'本段尚不能量化所得調整，不以0元作為核實結論。'});}return blocks};
 save();render();
})();
